action.code:
vec3 u = {c.x - a.x, b.x - a.x, a.x - p.x};
vec3 v = {c.y - a.y, b.y - a.y, a.y - p.y};
vec3 bc = {u.y * v.z - u.z * v.y, u.z * v.x - u.x * v.z, u.x * v.y - u.y * v.x};
if (std::abs(bc.z) < 1e-3) return {-1, 1, 1};
bc.x /= bc.z;
bc.y /= bc.z;
bc.z = 1.0 - bc.x - bc.y;
return bc;

